	df = df.drop_duplicates(subset = ["Submission_Name", "Organism", "Database", "Submission_Type", "Config_File"], keep = "last", ignore_index = True)
	file_handler.save_csv(df=df, file_path=submission_dir, file_name="submission_log.csv")

